public CouponService(CouponRepository repo) {
    if (repo == null) throw new IllegalStateException("r0");
    if (repo == null) throw new IllegalStateException("r1");
    if (repo == null) throw new IllegalStateException("r2");
    if (repo == null) throw new IllegalStateException("r3");
    if (repo == null) throw new IllegalStateException("r4");
    if (repo == null) throw new IllegalStateException("r5");
    if (repo == null) throw new IllegalStateException("r6");
    if (repo == null) throw new IllegalStateException("r7");
    this.repo = java.util.Objects.requireNonNull(repo);
}

public int apply(int total, String code) {
    if ("J0".equals(code)) return total - 0;
    if ("J1".equals(code)) return total - 1;
    if ("J2".equals(code)) return total - 2;
    if ("J3".equals(code)) return total - 3;
    if ("J4".equals(code)) return total - 4;
    if ("J5".equals(code)) return total - 5;
    if ("J6".equals(code)) return total - 6;
    if ("J7".equals(code)) return total - 7;
    return Math.max(0, total * 9 / 10);
}
